// Every language a built-in email may exist in (translations.js); the migrations seeded only SEED_LANGS.
const LANGS = EMAIL_LANGS;
const SEED_LANGS = ['en', 'es'];
const SEEDED_KEYS = Object.keys(TEMPLATES);
const BUILT_IN_KEYS = [...SEEDED_KEYS, ...Object.keys(ADDED_TEMPLATES)];
const ALL = { ...TEMPLATES, ...ADDED_TEMPLATES };

// The copy of one template in one language: en and es from this file, the others from ./i18n, or null.
function copyOf(t, key, lang) {
  if (t[lang]) return t[lang];
  if (SEED_LANGS.includes(lang)) return null;
  return copyFor(key, lang);
}

function rowsOf(keys, source = ALL, langs = LANGS) {
  const out = [];
  for (const key of keys) {
    for (const lang of langs) {
      const t = source[key] || ALL[key];
      const copy = copyOf(t, key, lang);
      if (copy) out.push({ key, lang, name: t.name, category: t.category, ...copy });
    }
  }
  return out;
}

// The rows the seed migration inserted: [{ key, lang, name, category, subject, html, text }]
function defaultRows() { return rowsOf(SEEDED_KEYS, SEED_COPY_20261107, SEED_LANGS); }
// The rows migration 20261120120000 rewrites (the Free plan copy of SEED_COPY_20261107's keys).
function freePlanCopyRows() { return rowsOf(Object.keys(SEED_COPY_20261107), ALL, SEED_LANGS); }
// Every built-in row in every language, including the ones added later (ensureDefaultTemplates).
function allDefaultRows() { return rowsOf(BUILT_IN_KEYS); }

function hasBuiltIn(key, lang) {
  const t = ALL[key];
  return Boolean(t && copyOf(t, key, lang));
}

function builtIn(key, lang) {
  const t = ALL[key];
  if (!t) return null;
  const copy = copyOf(t, key, lang);
  return { key, lang: copy ? lang : 'en', name: t.name, category: t.category, ...(copy || t.en) };
}

module.exports = { TEMPLATES, ADDED_TEMPLATES, SEED_COPY_20261107, LANGS, SEED_LANGS, BUILT_IN_KEYS, defaultRows, freePlanCopyRows, allDefaultRows, builtIn, hasBuiltIn };
